if barstate.isfirst
    // Log `Hello world!` on the first bar. The logged text does not include `"` characters. 
    log.info("Hello world!")

//@version=6
indicator("Quotes in single-line strings demo")

if barstate.isfirst
    // Log `"Hello world!"` on the first bar.
