//@version=6
indicator("Line wrapping within parentheses and brackets demo")

// We can enclose expressions in parentheses to wrap them across multiple lines using a four-space indentation.
float x = (open +
    high +              
    low +          
    close)

// We can wrap a long function call across two lines, for a minimal line wrapping style.
plot(ta.sma(close, 14), title = "Avg close", color = color.new(color.purple, 70), style = plot.style_area,
force_overlay = true, display = display.all - display.status_line)  // No indentation.

// We can apply any indentation to line wraps in square brackets as well.
[
    macd, signal, hist
] = ta.macd(x, 12, 26, 9)

// We can also apply different indentation lengths across the same line-wrapped expression.
// The enclosing parentheses or square brackets can start and end on separate lines from the wrapped content.
float osc = (
 signal                                                         // Indented by one space.
    + 2 * hist                                                  // Indented by four spaces.
        * math.abs(ta.change(macd, 10) / ta.stdev(macd, 10))    // Indented by eight spaces.
)                                                               // No indentation.

plot(
series = osc, title = "Custom osc",                             // No indentation.
  color = osc > osc[                                            // Indented by two spaces.
            1                                                   // Indented by 12 spaces.
    ] ? color.green : color.red,                                // Indented by four spaces.
      linewidth = 3                                             // Indented by six spaces.
         )                                                      // Indented by nine spaces.

//@version=6
indicator("Line wrapping with multiline strings demo", overlay = true)

//@variable A string indicating whether the bar is rising, falling, or neutral.
//          The strings in the ternary operations span multiple visible lines, but the entire expression is 
//          considered part of a single line. 
string labelText = close > open ? """
Bar is rising.
""" : close < open ? """
Bar is falling.
""" : """
Bar is neutral.
"""

// Draw a label to display the text from the current `labelText` string.
label.new(bar_index, close, labelText)

description:
Compiler annotations are comments that issue special instructions for a script:
//@version= specifies the PineScript version that the compiler will use. The number in this annotation should not be confused with the script's version number, which updates on every saved change to the code. //@description sets a custom description for scripts that use the library() declaration statement. //@function , //@param and //@returns add custom descriptions for a user-defined function or method , its parameters, and its result when placed above the function declaration. //@type adds a custom description for a user-defined type (UDT) when placed above the type declaration. //@enum adds a custom description for an enum types when placed above the enum declaration. //@field adds a custom description for the field of a user-defined type (UDT) or an enum types when placed above the type or enum declaration. //@variable adds a custom description for a variable when placed above its declaration. //@strategy_alert_message provides a default message for strategy scripts to pre-fill the “Message” field in the alert creation dialog.
The Pine Editor also features two specialized annotations, //#region and //#endregion , that create collapsible code regions. Clicking the dropdown arrow next to a //#region line collapses all the code between that line and the nearest //#endregion annotation below it.
This example draws a triangle using three interactively selected points on the chart. The script illustrates how one can use compiler and Editor annotations to document code and make it easier to navigate:
//@version=6
indicator("Triangle", "", true)

//#region ———————————————————— Constants and inputs

int   TIME_DEFAULT  = 0
float PRICE_DEFAULT = 0.0

x1Input = input.time(TIME_DEFAULT,   "Point 1", inline = "1", confirm = true)
y1Input = input.price(PRICE_DEFAULT, "",        inline = "1", tooltip = "Pick point 1", confirm = true)
x2Input = input.time(TIME_DEFAULT,   "Point 2", inline = "2", confirm = true)
y2Input = input.price(PRICE_DEFAULT, "",        inline = "2", tooltip = "Pick point 2", confirm = true)
x3Input = input.time(TIME_DEFAULT,   "Point 3", inline = "3", confirm = true)
y3Input = input.price(PRICE_DEFAULT, "",        inline = "3", tooltip = "Pick point 3", confirm = true)
//#endregion

//#region ———————————————————— Types and functions

// @type            Used to represent the coordinates and color to draw a triangle.
// @field time1     Time of first point.
// @field time2     Time of second point.
// @field time3     Time of third point.
// @field price1    Price of first point.
// @field price2    Price of second point.
// @field price3    Price of third point.
// @field lineColor Color to be used to draw the triangle lines.
type Triangle
    int   time1
    int   time2
    int   time3
    float price1
    float price2
    float price3
    color lineColor

//@function Draws a triangle using the coordinates of the `t` object.
//@param t  (Triangle) Object representing the triangle to be drawn.
//@returns  The ID of the last line drawn.
drawTriangle(Triangle t) =>
    line.new(t.time1, t.price1, t.time2, t.price2, xloc = xloc.bar_time, color = t.lineColor)
    line.new(t.time2, t.price2, t.time3, t.price3, xloc = xloc.bar_time, color = t.lineColor)
    line.new(t.time1, t.price1, t.time3, t.price3, xloc = xloc.bar_time, color = t.lineColor)
//#endregion

//#region ———————————————————— Calculations

// Draw the triangle only once on the last historical bar.
if barstate.islastconfirmedhistory
    //@variable Used to hold the Triangle object to be drawn.
    Triangle triangle = Triangle.new()

    triangle.time1  := x1Input
    triangle.time2  := x2Input
    triangle.time3  := x3Input
    triangle.price1 := y1Input
    triangle.price2 := y2Input
    triangle.price3 := y3Input
    triangle.lineColor := color.purple

    drawTriangle(triangle)
//#endregion

